package com.wheelwright.evidence.v2.portfolio;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.node.*;
import java.util.*;
import static com.wheelwright.evidence.v2.portfolio.PortfolioJson.*;
/** Compact rendering of already evaluated, authorization-sanitized Position facts. No economics here. */
public final class PortfolioTactical {
 private PortfolioTactical(){}
 private static ObjectNode fields(JsonNode s,String... names){var n=obj();for(String key:names)if(s.has(key))n.set(key,s.path(key).deepCopy());return n;}
 private static ObjectNode metric(JsonNode s){var n=fields(s,"value","unit","currency","status","warningCodes");if(s.hasNonNull("value")||Set.of("QUALIFIED","ESTABLISHED").contains(s.path("status").asText()))n.setAll(fields(s,"origin","method","asOf","assumptions"));return n;}
 public static ObjectNode project(ObjectNode position,Map<String,String> names,Map<String,String> standings){
  var n=fields(position,"id","self","account","state","currentConstruction");if(position.at("/exposure/status").isTextual())n.set("exposure",fields(position.path("exposure"),"status","sourceSnapshotId","sourceDate","receivedAt","continuity","qualification","successorPosition"));n.put("representation","TACTICAL_POSITION");n.set("details",position.path("self").deepCopy());
  var c=position.at("/included/construction");var recognition=fields(c.path("recognition"),"status","modelVersion","reasonCodes");recognition.set("authority",fields(c.at("/recognition/authority"),"claimId","basis","status","qualification","subjects","establishedAt"));String model=c.at("/recognition/modelVersion/href").asText();recognition.put("name",names.getOrDefault(model,c.at("/recognition/status").asText().equals("VALIDATED")?"Recognized construction":"Unclassified construction"));recognition.put("modelStanding",standings.getOrDefault(model,"UNKNOWN"));n.set("structure",recognition);
  var contracts=array();var underlyings=new TreeMap<String,String>();
  for(var leaf:leaves(c.path("composition"))){var item=fields(leaf,"nodeId","kind","quantity","unit","side","currency","instrument");if(leaf.has("terms"))item.set("terms",fields(leaf.path("terms"),"underlying","right","strike","currency","expiration","multiplier","exerciseStyle","settlement","adjustment","deliverable","payoffApplicability","qualification"));String uri=leaf.at("/instrument/href").asText();if(names.containsKey(uri))item.put("symbol",names.get(uri));contracts.add(item);String underlying=leaf.at("/terms/underlying/href").asText();if(!underlying.isBlank())underlyings.put(underlying,names.getOrDefault(underlying,"Unknown underlying"));}
  n.set("constituents",contracts);var subjects=array();underlyings.forEach((uri,symbol)->{var s=obj().put("symbol",symbol);s.set("instrument",link(uri));subjects.add(s);});n.set("underlyings",subjects);
  var e=position.path("evaluation");var value=fields(e,"evaluatedAt","freshness","oldestMaterialObservationAt");value.set("range",fields(e.path("range"),"status","kind","lower","upper","currency","warningCodes"));value.set("payoff",fields(e.path("payoff"),"status","geometry","evaluatedAt","assumptions","warningCodes"));for(String key:List.of("spot","grossUnrealizedPl","netUnrealizedPl","openingCashFlow","estimatedClosingCashFlow"))value.set(key,metric(e.path(key)));
  var tl=fields(e.path("timeline"),"openedAt","expiration","calendarZone","openingAccess");for(String key:List.of("remainingDays","originalDays"))tl.set(key,metric(e.path("timeline").path(key)));value.set("timeline",tl);
  var m=fields(e.path("management"),"access","associationStatus","stopInterpretation","protectiveOrderEvidence","manualCheckpoint","warningCodes");if(m.path("manualCheckpoint").isObject())m.set("manualCheckpoint",fields(m.path("manualCheckpoint"),"date","remainingDteAtCheckpoint","state","activeOrder","qualification","meaning","order"));for(String key:List.of("zeroGrossPl","profitTargetGrossPl","reportedStopThresholdGrossPl"))m.set(key,metric(e.path("management").path(key)));value.set("management",m);value.put("spotRegion",PortfolioMath.spotRegion(e));PortfolioMoneyness.apply(value,c);PortfolioPayoffPlot.apply(value);n.set("evaluation",value);var marketClock=PortfolioMarketClock.qualify(value);if(!marketClock.isEmpty())n.set("marketClock",marketClock);
  var codes=new TreeSet<String>();for(var source:List.of(position,c))for(var w:source.path("warnings"))codes.add(w.path("code").asText());var warnings=array();codes.forEach(warnings::add);n.set("warningCodes",warnings);return n;
 }
}
